DROP DATABASE IF EXISTS speedrun_phase4;
CREATE DATABASE speedrun_phase4 CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE speedrun_phase4;

CREATE TABLE users (user_id VARCHAR(32) PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, display_name VARCHAR(150) NOT NULL, joined_at DATETIME NOT NULL, is_admin BOOLEAN NOT NULL DEFAULT FALSE, active BOOLEAN NOT NULL DEFAULT TRUE, country_code CHAR(2), region_name VARCHAR(100));
CREATE TABLE game (game_id VARCHAR(32) PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, title_international VARCHAR(200) NOT NULL, title_local VARCHAR(200), release_year SMALLINT, source_url VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE category (category_id VARCHAR(32) PRIMARY KEY, name VARCHAR(150) NOT NULL, kind ENUM('full_game','per_level') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, game_id VARCHAR(32) NOT NULL, UNIQUE(game_id,name,kind), FOREIGN KEY(game_id) REFERENCES game(game_id) ON DELETE RESTRICT);
CREATE TABLE level (level_id VARCHAR(32) PRIMARY KEY, name VARCHAR(150) NOT NULL, display_order INT NOT NULL, game_id VARCHAR(32) NOT NULL, UNIQUE(game_id,name), UNIQUE(game_id,display_order), FOREIGN KEY(game_id) REFERENCES game(game_id) ON DELETE RESTRICT);
CREATE TABLE platform (platform_id VARCHAR(32) PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE, manufacturer VARCHAR(100));
CREATE TABLE permission (permission_code VARCHAR(32) PRIMARY KEY, description VARCHAR(255) NOT NULL);
CREATE TABLE supports (game_id VARCHAR(32) NOT NULL, platform_id VARCHAR(32) NOT NULL, PRIMARY KEY(game_id,platform_id), FOREIGN KEY(game_id) REFERENCES game(game_id), FOREIGN KEY(platform_id) REFERENCES platform(platform_id));
CREATE TABLE related_to (source_game_id VARCHAR(32) NOT NULL, related_game_id VARCHAR(32) NOT NULL, PRIMARY KEY(source_game_id,related_game_id), FOREIGN KEY(source_game_id) REFERENCES game(game_id), FOREIGN KEY(related_game_id) REFERENCES game(game_id), CHECK(source_game_id<>related_game_id));
CREATE TABLE game_alternate_name (game_id VARCHAR(32) NOT NULL, alternate_name VARCHAR(200) NOT NULL, PRIMARY KEY(game_id,alternate_name), FOREIGN KEY(game_id) REFERENCES game(game_id));
CREATE TABLE user_social_profile (user_id VARCHAR(32) NOT NULL, service VARCHAR(40) NOT NULL, url VARCHAR(500) NOT NULL, PRIMARY KEY(user_id,service,url), FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE authorizes (user_id VARCHAR(32) NOT NULL, game_id VARCHAR(32) NOT NULL, permission_code VARCHAR(32) NOT NULL, PRIMARY KEY(user_id,game_id,permission_code), FOREIGN KEY(user_id) REFERENCES users(user_id), FOREIGN KEY(game_id) REFERENCES game(game_id), FOREIGN KEY(permission_code) REFERENCES permission(permission_code));
CREATE TABLE leaderboard (board_id BIGINT AUTO_INCREMENT PRIMARY KEY, board_code VARCHAR(180) NOT NULL UNIQUE, variant_code VARCHAR(80) NOT NULL, variant_description VARCHAR(255) NOT NULL, timing_method ENUM('realtime','realtime_noloads','ingame') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, category_id VARCHAR(32) NOT NULL, platform_id VARCHAR(32) NOT NULL, level_id VARCHAR(32), FOREIGN KEY(category_id) REFERENCES category(category_id), FOREIGN KEY(platform_id) REFERENCES platform(platform_id), FOREIGN KEY(level_id) REFERENCES level(level_id), INDEX(category_id,platform_id,level_id));
CREATE TABLE board_rule_version (board_id BIGINT NOT NULL, version_no INT NOT NULL, rules_text TEXT NOT NULL, effective_at DATETIME NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY(board_id,version_no), FOREIGN KEY(board_id) REFERENCES leaderboard(board_id) ON DELETE RESTRICT, CHECK(effective_at>=created_at));
CREATE TABLE run_rule (submitted_at DATETIME NOT NULL, board_id BIGINT NOT NULL, version_no INT NOT NULL, PRIMARY KEY(submitted_at,board_id), FOREIGN KEY(board_id,version_no) REFERENCES board_rule_version(board_id,version_no));
CREATE TABLE run (run_id VARCHAR(32) PRIMARY KEY, run_date DATE NOT NULL, duration_ms BIGINT NOT NULL, note TEXT, runner_id VARCHAR(32) NOT NULL, submitter_id VARCHAR(32) NOT NULL, submitted_at DATETIME NOT NULL, board_id BIGINT NOT NULL, source_url VARCHAR(500), FOREIGN KEY(runner_id) REFERENCES users(user_id), FOREIGN KEY(submitter_id) REFERENCES users(user_id), FOREIGN KEY(submitted_at,board_id) REFERENCES run_rule(submitted_at,board_id), CHECK(duration_ms>0), INDEX(board_id,duration_ms), INDEX(runner_id));
CREATE TABLE evidence_link (run_id VARCHAR(32) NOT NULL, evidence_no INT NOT NULL, url VARCHAR(500) NOT NULL, kind VARCHAR(40) NOT NULL, label VARCHAR(150), PRIMARY KEY(run_id,evidence_no), UNIQUE(run_id,url), FOREIGN KEY(run_id) REFERENCES run(run_id) ON DELETE CASCADE, CHECK(evidence_no BETWEEN 1 AND 10));
CREATE TABLE review_event (run_id VARCHAR(32) NOT NULL, event_no INT NOT NULL, event_at DATETIME NOT NULL, outcome ENUM('verified','rejected','corrected') NOT NULL, note TEXT, author_id VARCHAR(32) NOT NULL, PRIMARY KEY(run_id,event_no), FOREIGN KEY(run_id) REFERENCES run(run_id) ON DELETE RESTRICT, FOREIGN KEY(author_id) REFERENCES users(user_id));
CREATE TABLE correction_change (run_id VARCHAR(32) NOT NULL, event_no INT NOT NULL, change_no INT NOT NULL, field_name VARCHAR(40) NOT NULL, evidence_no INT, old_value TEXT, new_value TEXT, PRIMARY KEY(run_id,event_no,change_no), FOREIGN KEY(run_id,event_no) REFERENCES review_event(run_id,event_no) ON DELETE CASCADE);
CREATE VIEW run_status AS SELECT r.run_id, COALESCE((SELECT CASE WHEN e.outcome='corrected' THEN 'new' ELSE e.outcome END FROM review_event e WHERE e.run_id=r.run_id ORDER BY e.event_no DESC LIMIT 1),'new') AS current_status FROM run r;
